69	    /**
70	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
71	     * domain containing at least one dot, with no whitespace in any part.
72	     */
73	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    /**
76	     * Common street-type abbreviations expanded during address normalization. Keys are the
77	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
78	     * expanded form it is replaced with.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
81	        "ST", "STREET",
82	        "RD", "ROAD",
83	        "AVE", "AVENUE");
