172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        currentOwner.setAddress(ownerFieldsDto.getAddress());
180	        currentOwner.setCity(ownerFieldsDto.getCity());
181	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
182	        currentOwner.setLastName(ownerFieldsDto.getLastName());
183	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
184	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
